document.addEventListener("DOMContentLoaded",()=>{const e=[{year:"1889",title:"Birth",description:"Born in Habibpur village of Midnapore district, Bengal."},{year:"1905",title:"Entry into Revolution",description:"Deeply affected by the partition of Bengal, he joined the Anushilan Samiti at age 15."},{year:"1908",title:"Muzaffarpur Bombing",description:"Tasked with assassinating Magistrate Douglas Kingsford. A bomb was thrown at a carriage believed to carry Kingsford, but it accidentally killed two European women."},{year:"August 1908",title:"Martyrdom",description:"He was tried and sentenced to death. At just 18 years old, he walked to the gallows with a smile and a copy of the Bhagavad Gita."}],t=document.getElementById("timeline-container");t&&e.forEach(e=>{const i=document.createElement("div");i.className="timeline-item",i.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,t.appendChild(i)});const i=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>i.observe(e));const n=[{title:"Anushilan Samiti",desc:"Joined this prominent revolutionary organization, engaging in physical culture and militant nationalism."},{title:"Distribution of Literature",desc:"Actively distributed secret pamphlets like 'Sonar Bangla' to inspire the youth."},{title:"Targeting Kingsford",desc:"Volunteered alongside Prafulla Chaki for the mission to assassinate Douglas Kingsford, the oppressive British magistrate."}],a=document.getElementById("activities-container");a&&n.forEach(e=>{const t=document.createElement("div");t.className="activity-card",t.tabIndex=0,t.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.desc}</p>\n            `,a.appendChild(t)});const s=[{step:"Arrest",desc:"Arrested at Waini station on May 1, 1908. He took full responsibility to protect his organization."},{step:"Investigation",desc:"British authorities conducted a swift investigation, relying on eyewitness accounts and confessions."},{step:"Trial",desc:"The trial began on May 21, 1908. Despite efforts by his defense lawyer, the verdict was predetermined."},{step:"Verdict & Execution",desc:"Sentenced to death. Executed on August 11, 1908."}],o=document.getElementById("trial-container");o&&s.forEach(e=>{const t=document.createElement("div");t.className="trial-step",t.innerHTML=`\n                <h3>${e.step}</h3>\n                <p>${e.desc}</p>\n            `,o.appendChild(t)});const r=document.getElementById("legacy-container");r&&(r.innerHTML="<div class=\"content-card\"><p>Khudiram Bose's execution ignited a fire of patriotism across India. His sacrifice became a powerful symbol of resistance against British rule. Songs celebrating his courage, like the famous 'Ekbar Biday De Ma Ghure Ashi', became anthems of the freedom struggle in Bengal.</p></div>");const d=[{text:"National Archives of India - Records of the Muzaffarpur Conspiracy Case",link:"#"},{text:"Dictionary of National Biography - Institute of Historical Studies",link:"#"},{text:"History of the Freedom Movement in India - Tara Chand",link:"#"}],c=document.getElementById("references-container");c&&d.forEach(e=>{const t=document.createElement("li");t.innerHTML="#"!==e.link?`<a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>`:`<span>${e.text}</span>`,c.appendChild(t)})});